5	namespace seed_b_backend.Api.Application;
6	
7	public class ProductQueryService(AppDbContext db)
8	{
9	    private const int PageSize = 20;
10	
11	    public async Task<PagedResultDto<ProductListItemDto>> GetProductsAsync(
12	        int page = 1,
13	        CancellationToken cancellationToken = default)
14	    {
15	        if (page < 1)
16	        {
17	            page = 1;
18	        }
19	
20	        var query = db.Products.AsNoTracking().OrderBy(p => p.Id);
21	
22	        var totalCount = await query.CountAsync(cancellationToken);
23	        var pageCount = totalCount == 0 ? 0 : (int)Math.Ceiling(totalCount / (double)PageSize);
24	
25	        var items = await query
26	            .Skip((page - 1) * PageSize)
27	            .Take(PageSize)
28	            .Select(p => new ProductListItemDto
29	            {
30	                Id = p.Id,
31	                Name = p.Name,
32	                LowestPrice = p.Offers.Select(o => (decimal?)o.Price).Min()
33	            })
34	            .ToListAsync(cancellationToken);
35	
36	        return new PagedResultDto<ProductListItemDto>
37	        {
38	            Items = items,
39	            TotalCount = totalCount,
40	            PageCount = pageCount,
41	            Page = page,
42	            PageSize = PageSize
43	        };
44	    }
45	}
