                .WithMany(s => s.PropertyDefinitions)
                .HasForeignKey(pd => pd.SubcategoryId);
        });

        modelBuilder.Entity<Product>(entity =>
        {
            entity.HasKey(p => p.Id);
            entity.HasIndex(p => p.SubcategoryId);
